{
  "name": "opencode-task-complete",
  "version": "0.1.1",
  "description": "OpenCode V2 plugin: the task_complete tool - the model's explicit 'I am finished' signal, with the v1 todo gate and ack self-loop guard, observable by any plugin.",
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": {
      "import": "./index.js"
    }
  },
  "files": [
    "index.js",
    "examples",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "bun test test/",
    "prepublishOnly": "npm pack --dry-run"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "task-complete",
    "task_complete",
    "completion",
    "stall",
    "watcher"
  ],
  "license": "MIT",
  "author": "famewolf",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/famewolf/opencode-task-complete.git"
  },
  "homepage": "https://github.com/famewolf/opencode-task-complete",
  "bugs": {
    "url": "https://github.com/famewolf/opencode-task-complete/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "opencode": ">=2.0.0"
  }
}
